mapper.select:
select uwa.*, su.avatar as userAvatar,su.nickname as userName,su.phone as userPhone from ums_withdraw_account uwa left join sys_user su on su.id=uwa.user_id where 1 = 1
and uwa.user_id = #{paramCondition.userId}
and uwa.account_type = #{paramCondition.accountType}
and (su.nickname like CONCAT('%',#{paramCondition.keyword},'%') or su.phone like CONCAT('%',#{paramCondition.keyword},'%') or uwa.account like CONCAT('%',#{paramCondition.keyword},'%') or uwa.realname like CONCAT('%',#{paramCondition.keyword},'%') )
order by uwa.create_time desc
